verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        register_schema_request -> v_msg_register_schema_request(Msg, [MsgName], TrUserData);
        unregister_schema_request -> v_msg_unregister_schema_request(Msg, [MsgName], TrUserData);
        get_schema_request -> v_msg_get_schema_request(Msg, [MsgName], TrUserData);
        list_schemas_request -> v_msg_list_schemas_request(Msg, [MsgName], TrUserData);
        get_schema_version_request -> v_msg_get_schema_version_request(Msg, [MsgName], TrUserData);
        upcast_events_request -> v_msg_upcast_events_request(Msg, [MsgName], TrUserData);
        register_schema_response -> v_msg_register_schema_response(Msg, [MsgName], TrUserData);
        unregister_schema_response -> v_msg_unregister_schema_response(Msg, [MsgName], TrUserData);
        get_schema_response -> v_msg_get_schema_response(Msg, [MsgName], TrUserData);
        list_schemas_response -> v_msg_list_schemas_response(Msg, [MsgName], TrUserData);
        get_schema_version_response -> v_msg_get_schema_version_response(Msg, [MsgName], TrUserData);
        upcast_events_response -> v_msg_upcast_events_response(Msg, [MsgName], TrUserData);
        proposed_event -> v_msg_proposed_event(Msg, [MsgName], TrUserData);
        recorded_event -> v_msg_recorded_event(Msg, [MsgName], TrUserData);
        snapshot_record -> v_msg_snapshot_record(Msg, [MsgName], TrUserData);
        subscription_info -> v_msg_subscription_info(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,v_msg_register_schema_request/3}).
-dialyzer({nowarn_function,v_msg_register_schema_request/3}).
v_msg_register_schema_request(#{} = M, Path, TrUserData) ->
    case M of
        #{store_id := F1} -> v_type_string(F1, [store_id | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{event_type := F2} -> v_type_string(F2, [event_type | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{schema := F3} -> v_type_bytes(F3, [schema | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (store_id) -> ok;
                      (event_type) -> ok;
                      (schema) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_register_schema_request(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), register_schema_request}, M, Path);
v_msg_register_schema_request(X, Path, _TrUserData) -> mk_type_error({expected_msg, register_schema_request}, X, Path).

